#!/usr/bin/env bash
# Applied by "cka verify". Generated by Quick Create.
set -euo pipefail

# Question 1: Worker after a configuration change
case "${Q1_FAULT}" in
  kubelet-eviction-hard)
    for _ in $(seq 1 90); do
      ready=$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}')
      press=$(kubectl get node "${Q1_NODE}" -o jsonpath='{.status.conditions[?(@.type=="MemoryPressure")].status}')
      [[ "$ready" == True && "$press" == False ]] && break
      sleep 2
    done
    for _ in $(seq 1 60); do
      ready=$(kubectl -n "${Q1_NS}" get daemonset node-agent -o jsonpath='{.status.numberReady}')
      want=$(kubectl -n "${Q1_NS}" get daemonset node-agent -o jsonpath='{.status.desiredNumberScheduled}')
      [[ "$ready" == "$want" && -n "$ready" ]] && break
      sleep 3
    done
    ;;
esac
